// ==UserScript==
// @name         Claude Browser Completion Chime
// @namespace    https://github.com/lytken-de/claude-browser-completion-chime
// @version      1.8.1
// @description  Plays an audio notification when Claude.ai finishes generating a response (when the stop button disappears).
// @author       lytken-de
// @license      MIT
// @homepageURL  https://github.com/lytken-de/claude-browser-completion-chime
// @supportURL   https://github.com/lytken-de/claude-browser-completion-chime/issues
// @updateURL    https://raw.githubusercontent.com/lytken-de/claude-browser-completion-chime/main/claude-browser-completion-chime.user.js
// @downloadURL  https://raw.githubusercontent.com/lytken-de/claude-browser-completion-chime/main/claude-browser-completion-chime.user.js
// @match        https://claude.ai/*
// @run-at       document-idle
// @grant        none
// @sandbox      raw
// ==/UserScript==

(function () {
  'use strict';

  // ---------- Settings ----------
  const CONFIG = {
    SHOW_NOTIFICATION: true,    // browser notification (asks for permission on your first click on the page)
    ONLY_IN_BACKGROUND: false,  // true = only chime/notify when the tab is not focused
    MIN_DURATION_MS: 1500,      // the stop button must have been visible at least this long, otherwise no chime
    DONE_DELAY_MS: 2000,        // the stop button must stay gone this long before it counts as "done"
                                // (if it comes back within this time, it's the same response – no chime)
    VOLUME: 1.0,                // 1.0 = the sound file's own volume, 0.5 = half
    KEEP_AWAKE: false,          // very faint noise while Claude works, so Bluetooth audio doesn't fall asleep
    SILENCE_BEFORE_MS: 0,       // extra silence before the chime
    DEBUG: false,               // true = log state changes to the console
  };

  // Fallback only: the whole label must BE a stop label. (Message action buttons carry the
  // full message text in their label, e.g. "Show message actions for You said: … stop …",
  // so a loose "contains stop" match would fire while scrolling through old messages.)
  const STOP_PATTERN = /^(stop|stop response|stop generating|interrupt)$/i;
  const log = (...a) => CONFIG.DEBUG && console.log('[Claude-chime]', ...a);

  // ---------- Find the stop button ----------
  function isVisible(el) {
    if (!el.isConnected) return false;
    const r = el.getBoundingClientRect();
    return r.width > 0 && r.height > 0;
  }

  function stopButtons() {
    // Reliable match: Claude.ai's own stop button.
    const known = [...document.querySelectorAll('[data-testid="chat-input-stop"]')].filter(isVisible);
    if (known.length) return known;
    // Fallback: anything acting as a button whose label mentions stop/interrupt.
    return [...document.querySelectorAll('button,[role="button"]')].filter((b) => {
      const labels = [b.getAttribute('aria-label'), b.getAttribute('title')].filter(Boolean);
      return labels.some((l) => STOP_PATTERN.test(l.trim())) && isVisible(b);
    });
  }

  // ---------- Audio ----------
  let audioCtx = null;
  function getAudioContext() {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    return audioCtx;
  }

  // Browsers only allow audio after a click/keypress on the page: unlock it on the first one,
  // and ask for notification permission if needed.
  function onFirstInteraction() {
    getAudioContext().resume();
    if (CONFIG.SHOW_NOTIFICATION && 'Notification' in window && Notification.permission === 'default') {
      Notification.requestPermission();
    }
  }
  ['pointerdown', 'keydown'].forEach((t) => window.addEventListener(t, onFirstInteraction, { capture: true }));

  // The chime (announcement-sound.mp3) is embedded, so nothing is fetched from the network.
  // It is decoded once and played directly as a buffer – no oscillator/gain automation,
  // which some anti-fingerprinting tools (e.g. AdGuard) interfere with.
  const CHIME_MP3_BASE64 = '';
  let chimeBuffer = null;
  let chimeLoading = null;

  function loadChime(ctx) {
    if (chimeBuffer) return Promise.resolve(chimeBuffer);
    if (!chimeLoading) {
      const bin = atob(CHIME_MP3_BASE64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      chimeLoading = ctx.decodeAudioData(bytes.buffer).then((sound) => {
        // New buffer: optional silence first, then the sound scaled to VOLUME.
        const offset = Math.round(sound.sampleRate * CONFIG.SILENCE_BEFORE_MS / 1000);
        const buf = ctx.createBuffer(sound.numberOfChannels, offset + sound.length, sound.sampleRate);
        for (let ch = 0; ch < sound.numberOfChannels; ch++) {
          const src = sound.getChannelData(ch);
          const dst = buf.getChannelData(ch);
          for (let i = 0; i < src.length; i++) dst[offset + i] = src[i] * CONFIG.VOLUME;
        }
        chimeBuffer = buf;
        return buf;
      });
    }
    return chimeLoading;
  }

  // ---------- Keep the audio output awake ----------
  // Bluetooth headphones/speakers sleep when there is no signal and swallow the start
  // of a short sound. With KEEP_AWAKE, a very faint noise (~ -60 dB) plays while Claude works.
  let keepAwakeSource = null;
  function startKeepAwake() {
    if (!CONFIG.KEEP_AWAKE || keepAwakeSource) return;
    try {
      const ctx = getAudioContext();
      ctx.resume();
      const sr = ctx.sampleRate;
      const buf = ctx.createBuffer(1, sr, sr);
      const d = buf.getChannelData(0);
      for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * 0.0005;
      keepAwakeSource = ctx.createBufferSource();
      keepAwakeSource.buffer = buf;
      keepAwakeSource.loop = true;
      keepAwakeSource.connect(ctx.destination);
      keepAwakeSource.start();
      log('Keeping audio output awake');
    } catch (e) { console.warn('[Claude-chime] Could not keep audio awake:', e); }
  }
  function stopKeepAwake(afterMs = 0) {
    const s = keepAwakeSource;
    keepAwakeSource = null;
    if (!s) return;
    setTimeout(() => { try { s.stop(); } catch (e) {} log('Stopped keep-awake'); }, afterMs);
  }

  function playChime() {
    const ctx = getAudioContext();
    ctx.resume();
    loadChime(ctx).then((buf) => {
      const source = ctx.createBufferSource();
      source.buffer = buf;
      source.connect(ctx.destination);
      source.start();
      stopKeepAwake(buf.duration * 1000 + 300);
      log('Chime played, audio state:', ctx.state);
    }).catch((e) => console.warn('[Claude-chime] Could not play the chime:', e));
  }

  function showNotification() {
    if (!CONFIG.SHOW_NOTIFICATION || !('Notification' in window) || Notification.permission !== 'granted') return;
    if (document.hasFocus()) return; // no need to notify while you're looking at the tab
    const n = new Notification('Claude is done', {
      body: document.title.replace(/\s*[-–|]\s*Claude\s*$/i, '') || 'Your response is ready',
      silent: true,
    });
    n.onclick = () => { window.focus(); n.close(); };
  }

  // ---------- Watch for the stop button ----------
  // The stop button can disappear briefly in the middle of a response (e.g. while the page
  // re-renders). So "done" only counts once it has stayed gone for DONE_DELAY_MS.
  // If Claude stops to ask for your approval (e.g. a tool permission), the button stays
  // gone – and that chimes too, because Claude is waiting for you.
  let working = false;
  let startTime = 0;
  let startPath = location.pathname;
  let goneAt = 0;
  let pendingFinish = null;

  function check() {
    const nowWorking = stopButtons().length > 0;

    if (nowWorking) {
      if (pendingFinish) {
        clearTimeout(pendingFinish);
        pendingFinish = null;
        log('Stop button back after', Date.now() - goneAt, 'ms – same response');
      }
      if (!working) {
        working = true;
        startTime = Date.now();
        startPath = location.pathname;
        log('Claude is working', startPath);
        startKeepAwake();
      }
      return;
    }

    if (working && !pendingFinish) {
      goneAt = Date.now();
      log('Stop button gone – waiting', CONFIG.DONE_DELAY_MS, 'ms to be sure');
      pendingFinish = setTimeout(finish, CONFIG.DONE_DELAY_MS);
    }
  }

  function finish() {
    pendingFinish = null;
    if (stopButtons().length > 0) return; // came back at the last moment – keep waiting
    working = false;
    const duration = goneAt - startTime;
    // If you switched to another chat yourself, that's not "done".
    if (location.pathname !== startPath) { log('Page changed – no chime'); stopKeepAwake(); return; }
    if (duration < CONFIG.MIN_DURATION_MS) { log('Too short –', duration, 'ms'); stopKeepAwake(); return; }
    if (CONFIG.ONLY_IN_BACKGROUND && document.hasFocus()) { log('Tab is focused – no chime'); stopKeepAwake(); return; }

    log('Done after', duration, 'ms');
    playChime();
    showNotification();
  }

  new MutationObserver(check).observe(document.body, {
    childList: true, subtree: true, attributes: true,
    attributeFilter: ['aria-label', 'title', 'data-testid', 'style', 'class', 'hidden'],
  });
  setInterval(check, 1000); // safety net in case a change is missed

  // Test from the console: claudeChimeTest()
  window.claudeChimeTest = () => { playChime(); return 'Played test chime'; };

  console.log('[Claude-chime] v1.8.1 loaded – test with claudeChimeTest()');
})();
